package dashboard

const pages = `{{define "head"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="refresh" content="15"><title>OpenFactory feature lanes</title><link rel="stylesheet" href="/assets/dashboard.css"></head><body><header><a href="/">OpenFactory lanes</a><a href="/programs">Discovery programs</a><span>Read-only · refreshes every 15 seconds</span></header><main>{{end}}
{{define "foot"}}{{if .Feature.Feature.ID}}<section><h2>Dependency gates</h2><ul>{{range .Feature.Dependencies}}<li><a href="{{featureURL .ID}}">{{.ID}}</a> · {{.State}} · {{if .Satisfied}}satisfied{{else}}not satisfied{{end}}</li>{{else}}<li>No dependency gates.</li>{{end}}</ul></section><section><h2>Stage timeline</h2>{{range .Feature.Timeline}}<article><h3>{{.Stage}} · {{.State}}</h3><p>Attempt {{.AttemptID}} · {{.StartedAt}} → {{if .FinishedAt}}{{.FinishedAt}}{{else}}ongoing{{end}}</p></article>{{else}}<p>No stage intervals recorded.</p>{{end}}</section>{{end}}</main><footer>Durable observations, not estimated progress. Evidence only applies to its exact candidate and generation.</footer></body></html>{{end}}
{{define "overview"}}{{template "head" .}}<h1>Feature lanes</h1><p>Observed {{.Status.ObservedAt}} · {{if .Status.Paused}}<strong>Paused — no new work</strong>{{else}}Admission enabled{{end}}</p><section class="metrics"><article><h2>Global lanes</h2><strong>{{.Status.Limits.Global.Active}} / {{.Status.Limits.Global.Limit}}</strong> active</article><article><h2>Daily model calls</h2><strong>{{.Status.Calls.Used}} / {{.Status.Calls.Limit}}</strong><br>{{.Status.Calls.Day}}</article>{{range .Status.Limits.Projects}}<article><h2>{{.Name}}</h2><strong>{{.Active}} / {{.Limit}}</strong> active</article>{{end}}</section><form method="get" action="/"><label>Project <input name="project" value="{{.Project}}"></label><label>State <input name="state" value="{{.State}}" placeholder="e.g. running"></label><button type="submit">Filter view</button><a href="/">Clear</a></form><div class="scroll"><table><thead><tr><th>Feature</th><th>Project / target</th><th>State / stage</th><th>Wait / queue</th><th>Dependencies</th><th>Candidate</th></tr></thead><tbody>{{range .Status.Features}}<tr><td><a href="{{featureURL .Feature.ID}}">{{.Feature.ID}}</a><br>{{.Feature.Title}}{{if .Feature.DiscoveryStepID}}<br><strong>Internal discovery step</strong>{{end}}</td><td>{{.Feature.Project}}<br>{{.Feature.CompletionTarget}}</td><td>{{.Feature.State}}{{range .Attempts}}{{if .Active}}<br><strong>{{.Stage}}</strong>{{end}}{{end}}</td><td>{{if .Wait}}{{.Wait.Code}}{{if .Wait.FeatureID}} · {{.Wait.FeatureID}}{{end}}{{if .Wait.OwnerID}} · owner {{.Wait.OwnerID}}{{end}}{{else}}—{{end}}{{if .Integration.State}}<br>{{.Integration.State}} · position {{.Integration.Position}}{{end}}</td><td>{{range .Feature.DependsOn}}<a href="{{featureURL .}}">{{.}}</a> {{else}}None{{end}}</td><td>{{range .Attempts}}{{if .Active}}gen {{.CandidateGeneration}}<br><code>{{short .CandidateSHA}}</code>{{end}}{{end}}</td></tr>{{else}}<tr><td colspan="6">No features match this view. Features appear after they are ingested.</td></tr>{{end}}</tbody></table></div>{{if .Next}}<a class="next" href="{{.Next}}">Next features →</a>{{end}}{{template "foot" .}}{{end}}
{{define "proof"}}<article class="proof"><strong>{{.Kind}} · {{if .Passed}}passed{{else}}not passed{{end}}</strong><p>Attempt <code>{{.AttemptID}}</code> · generation {{.CandidateGeneration}} · candidate <code>{{.CandidateSHA}}</code> · {{.CreatedAt}}</p><pre>{{bounded .Detail}}</pre></article>{{end}}
{{define "detail"}}{{template "head" .}}<h1>{{.Feature.Feature.ID}} · {{.Feature.Feature.Title}}</h1><p>{{.Feature.Feature.Project}} · {{.Feature.Feature.State}} · target {{.Feature.Feature.CompletionTarget}} · risk {{.Feature.Feature.Risk}}</p>{{if .Feature.Feature.Reason}}<p>{{bounded .Feature.Feature.Reason}}</p>{{end}}<p>Dependencies: {{range .Feature.Feature.DependsOn}}<a href="{{featureURL .}}">{{.}}</a> {{else}}None{{end}}</p>
{{if .Feature.Feature.DiscoveryStepID}}<p><strong>Internal discovery step</strong> · <code>{{.Feature.Feature.DiscoveryStepID}}</code> · consumes ordinary global capacity; not a product implementation proposal. <a href="/programs">Browse discovery programs</a></p>{{end}}
{{if .Feature.Wait}}<section><h2>Waiting: {{.Feature.Wait.Code}}</h2><p>{{bounded .Feature.Wait.Detail}}</p><p>Dependency {{.Feature.Wait.FeatureID}} · owner {{.Feature.Wait.OwnerID}} · resource {{.Feature.Wait.Resource}}</p></section>{{end}}
<section><h2>Serialized delivery ownership</h2><p>State: {{.Feature.Integration.State}} · FIFO position {{.Feature.Integration.Position}} · owner <code>{{.Feature.Integration.OwnerAttemptID}}</code></p><ul>{{range .Feature.Integration.Resources}}<li><code>{{.}}</code></li>{{else}}<li>No delivery resources reserved.</li>{{end}}</ul></section>
{{if .Feature.Receipt}}<section><h2>Delivery receipt</h2>{{if receiptURL .Feature.Receipt}}<a rel="noreferrer noopener" href="{{receiptURL .Feature.Receipt}}">{{.Feature.Receipt}}</a>{{else}}<pre>{{bounded .Feature.Receipt}}</pre>{{end}}</section>{{end}}
<section><h2>Attempt history</h2>{{range .Feature.Attempts}}<article><h3>{{.ID}} · {{.State}} · {{.Stage}} {{if .Active}}(active){{end}}</h3><dl><dt>Started / stage started / updated</dt><dd>{{.StartedAt}} / {{.StageStartedAt}} / {{.UpdatedAt}}</dd><dt>Deadline</dt><dd>{{.Deadline}}</dd><dt>Candidate generation</dt><dd>{{.CandidateGeneration}}</dd><dt>Base → candidate</dt><dd><code>{{.BaseSHA}} → {{.CandidateSHA}}</code></dd><dt>Immutable source base → candidate</dt><dd><code>{{.SourceBaseSHA}} → {{.SourceCandidateSHA}}</code></dd></dl></article>{{else}}<p>No attempts yet.</p>{{end}}</section>
<section><h2>Check history</h2><p>Each row records its own candidate; older generations do not prove the current candidate.</p>{{range .Feature.Checks}}<article><h3>{{.Name}} · {{.State}}</h3><p>Attempt {{.AttemptID}} · gen {{.CandidateGeneration}} · <code>{{.CandidateSHA}}</code></p><p>{{.StartedAt}} → {{.UpdatedAt}}</p><pre>{{bounded .Detail}}</pre></article>{{else}}<p>No checks recorded.</p>{{end}}</section>
<section><h2>Current candidate evidence</h2>{{range .Feature.CurrentEvidence}}{{template "proof" .}}{{else}}<p>No proof for the current candidate.</p>{{end}}</section>
<section><h2>Evidence history (including superseded candidates)</h2><p><a href="{{featureURL .Feature.Feature.ID}}">Show latest histories</a></p>{{range .Evidence.Items}}{{template "proof" .}}{{else}}<p>No evidence recorded.</p>{{end}}{{if .NextEvidence}}<a href="{{.NextEvidence}}">Older evidence →</a>{{end}}</section>
<section><h2>Model sessions</h2>{{range .Feature.Sessions}}<article><h3>{{.Stage}} · {{.CreatedAt}}</h3><dl><dt>Attempt / dispatch</dt><dd>{{.AttemptID}} / {{.DispatchKey}}</dd><dt>Thread</dt><dd><code>{{.ThreadID}}</code></dd><dt>Environment</dt><dd><code>{{.EnvironmentID}}</code></dd></dl></article>{{else}}<p>No sessions recorded.</p>{{end}}</section>
<section><h2>Events</h2><p><a href="{{featureURL .Feature.Feature.ID}}">Show latest histories</a></p>{{range .Events.Items}}<article><h3>{{.Kind}} · {{.CreatedAt}}</h3><pre>{{.Detail}}</pre></article>{{else}}<p>No events recorded.</p>{{end}}{{if .NextEvents}}<a href="{{.NextEvents}}">Older events →</a>{{end}}</section>
<p><a href="/api/features/{{.Feature.Feature.ID}}">Feature JSON</a> · <a href="/api/features/{{.Feature.Feature.ID}}/events">Event JSON</a> · <a href="/api/features/{{.Feature.Feature.ID}}/evidence">Evidence JSON</a></p>{{template "foot" .}}{{end}}`

const styles = `:root{color-scheme:light dark;font-family:system-ui,sans-serif;line-height:1.5}body{margin:0;background:#101720;color:#e3ebf4}header,footer{padding:1rem 3vw;background:#192532;display:flex;gap:2rem;flex-wrap:wrap}main{max-width:1500px;margin:auto;padding:1rem 3vw}a{color:#8dccff}header a{font-weight:700}h1{font-size:1.8rem}h2{font-size:1.25rem}h3{font-size:1rem}section{margin:1.5rem 0}.metrics{display:flex;gap:1rem;flex-wrap:wrap}article{padding:1rem;background:#192532;border:1px solid #34485c;border-radius:.3rem;margin:.7rem 0}.metrics article{min-width:10rem}form{display:flex;gap:1rem;flex-wrap:wrap;align-items:end;margin:2rem 0}label{display:grid;gap:.25rem}input,button{padding:.6rem;font:inherit}button{cursor:pointer}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{padding:.8rem;text-align:left;vertical-align:top;border-bottom:1px solid #34485c}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:30rem;overflow:auto}code,dd{overflow-wrap:anywhere}dt{font-weight:bold}dd{margin:0 0 .8rem}.next{display:block;margin:1rem 0}footer{margin-top:2rem;color:#bccbdc;font-size:.9rem}`
